import {scriptLibrary} from './script-library.js';
const $ = s => document.querySelector(s);
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=new Set(['overview','devices','companies','groups','backups','security','patches','network','directory','scripts','tickets','ai','providers','monitoring']);
const pageFromUrl=()=>pages.has(location.hash.slice(1))?location.hash.slice(1):'overview';
let inventory = {groups:[],customers:[],companies:[],locations:[],deviceGroups:[],devices:[]}, refreshing = false, page = pageFromUrl();
const dashboardWidgets=[{id:'dashboard-stats',name:'Inventory totals'},{id:'dashboard-endpoints',name:'Endpoint status'},{id:'dashboard-coverage',name:'Protection overview'},{id:'dashboard-alerts',name:'Priority alerts'},{id:'dashboard-inventory',name:'Inventory table'},{id:'dashboard-quick',name:'Quick tools'},{id:'companies-panel',name:'Customers & companies'},{id:'devices-panel',name:'Computer cards and live metrics'},{id:'backups-panel',name:'Backup providers'}];
const defaultDashboard=()=>({columns:3,order:dashboardWidgets.map(w=>w.id),hidden:['companies-panel','devices-panel','backups-panel']});
function normalizeDashboard(value){if(!value||typeof value!=='object')return defaultDashboard();const ids=dashboardWidgets.map(w=>w.id);return {columns:[1,2,3].includes(value?.columns)?value.columns:1,order:[...new Set([...(Array.isArray(value?.order)?value.order.filter(id=>ids.includes(id)):[]),...ids])],hidden:Array.isArray(value?.hidden)?[...new Set(value.hidden.filter(id=>ids.includes(id)))]:[]};}
let dashboard=defaultDashboard();try{dashboard=normalizeDashboard(JSON.parse(localStorage.getItem('skybase-dashboard-layout')));}catch{}
function applyDashboard(){
  const target=$('#dashboard-layout'),isDashboard=page==='overview';target.hidden=!isDashboard;$('#customize-dashboard').hidden=!isDashboard;
  target.className='dashboard-layout dashboard-columns-'+dashboard.columns;
  for(const id of dashboard.order){
    const widget=$('#'+id);
    if(isDashboard){target.append(widget);widget.hidden=dashboard.hidden.includes(id);}
    else{$('#workspace').insertBefore(widget,$('#groups-panel'));widget.hidden=id.startsWith('dashboard-')&&id!=='dashboard-stats'||id==='companies-panel'&&page!=='companies'||id==='devices-panel'&&page!=='devices'||id==='backups-panel'&&page!=='backups';}
  }
  if(isDashboard&&!dashboard.hidden.includes('backups-panel')){loadAcronis();loadBackupProviders();}
  if(isDashboard&&dashboard.hidden.length===dashboardWidgets.length){target.append($('#dashboard-empty'));$('#dashboard-empty').hidden=false;}else $('#dashboard-empty').hidden=true;
}
function customizeDashboard(){
  let draft=normalizeDashboard(dashboard);
  function draw(){
    showDialog(`<h2>Customize dashboard</h2><p class="muted">Choose existing widgets, move them into your preferred order, and select a layout. Settings are saved in this browser.</p><label>Columns<select id="dashboard-columns">${[1,2,3].map(n=>`<option value="${n}" ${n===draft.columns?'selected':''}>${n} column${n===1?'':'s'}</option>`).join('')}</select></label><div>${draft.order.map((id,index)=>`<div class="widget-setting"><label><input type="checkbox" data-widget-toggle="${id}" ${draft.hidden.includes(id)?'':'checked'}>${escape(dashboardWidgets.find(w=>w.id===id).name)}</label><div><button type="button" data-widget-move="${id}" data-direction="-1" aria-label="Move ${escape(dashboardWidgets.find(w=>w.id===id).name)} up" ${index===0?'disabled':''}>↑</button><button type="button" data-widget-move="${id}" data-direction="1" aria-label="Move ${escape(dashboardWidgets.find(w=>w.id===id).name)} down" ${index===draft.order.length-1?'disabled':''}>↓</button></div></div>`).join('')}</div><p id="dashboard-save-error" role="alert"></p><div class="actions"><button id="dashboard-reset" type="button">Reset layout</button><button data-close>Cancel</button><button class="primary" id="dashboard-save">Save layout</button></div>`);
    $('#dashboard-columns').onchange=e=>draft.columns=Number(e.target.value);
    document.querySelectorAll('[data-widget-toggle]').forEach(input=>input.onchange=()=>{draft.hidden=input.checked?draft.hidden.filter(id=>id!==input.dataset.widgetToggle):[...draft.hidden,input.dataset.widgetToggle];});
    bind('[data-widget-move]',b=>{const index=draft.order.indexOf(b.dataset.widgetMove),next=index+Number(b.dataset.direction);[draft.order[index],draft.order[next]]=[draft.order[next],draft.order[index]];$('#modal').close();draw();});
    $('#dashboard-reset').onclick=()=>{draft=defaultDashboard();$('#modal').close();draw();};
    $('#dashboard-save').onclick=()=>{try{localStorage.setItem('skybase-dashboard-layout',JSON.stringify(draft));dashboard=normalizeDashboard(draft);$('#modal').close();applyDashboard();}catch{$('#dashboard-save-error').textContent='Your browser blocked saving. Allow site storage and try again.';}};
  }
  draw();
}
async function api(path, data) {
  const response = await fetch('/api/' + path, {method:data === undefined ? 'GET' : 'POST',headers:data === undefined ? {} : {'Content-Type':'application/json'},body:data === undefined ? undefined : JSON.stringify(data)});
  const value = await response.json();
  if (response.status === 401) { $('#modal').close(); $('#workspace').hidden = true; $('#logout').hidden = true; $('#login').hidden = false; }
  if (!response.ok) throw new Error(value.error || 'Request failed.');
  return value;
}
function message(text) { $('#message').textContent = text; }
function options(items, selected, empty) { return (empty ? `<option value="">${empty}</option>` : '') + items.map(x => `<option value="${escape(x.id)}" ${x.id === selected ? 'selected' : ''}>${escape(x.name)}</option>`).join(''); }
function setFilter(id, items, empty) { const value=$(id).value; $(id).innerHTML=options(items,value,empty); }
function devicesFiltered() {
  const company=$('#company-filter').value,location=$('#location-filter').value,group=$('#group-filter').value,status=$('#status-filter').value,query=$('#search').value.toLowerCase();
  return inventory.devices.filter(d => (!company || d.companyId===company) && (!location || d.locationId===location) && (!group || d.groupId===group) && (!status || d.online===(status==='online')) && `${d.name} ${d.company} ${d.location} ${d.groupName} ${d.os}`.toLowerCase().includes(query));
}
function changePage(value,updateUrl=false) {
  page=pages.has(value)?value:'overview';
  if(updateUrl&&location.hash!=='#'+page){const url=new URL(location.href);url.hash=page;history.pushState(null,'',url);}
  document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);b.setAttribute('aria-current',b.dataset.page===page?'page':'false');});
  $('#companies-panel').hidden=!['overview','companies'].includes(page);
  $('#devices-panel').hidden=!['overview','devices'].includes(page);
  $('#backups-panel').hidden=page!=='backups';
  if(page==='backups'){loadAcronis();loadBackupProviders();}
  $('#groups-panel').hidden=page!=='groups';
  $('#monitoring-panel').hidden=page!=='monitoring';if(page==='monitoring'||page==='overview')loadMonitoring();else clearTimeout(monitorTimer);
  $('#provider-panel').hidden=page!=='providers';if(page==='providers')loadProviderRegistry();
  $('#ai-panel').hidden=page!=='ai';if(page==='ai')loadAgents();
  $('#tickets-panel').hidden=page!=='tickets';if(page==='tickets')loadTickets();
  $('#scripts-panel').hidden=page!=='scripts';if(page==='scripts')renderScripts();
  $('#directory-panel').hidden=page!=='directory';if(page==='directory'){renderDirectorySelectors();loadDirectory();}else clearTimeout(directoryTimer);
  $('#network-panel').hidden=page!=='network';if(page==='network'){renderNetworkSites();loadNetwork();}else clearTimeout(networkTimer);
  $('#patches-panel').hidden=page!=='patches';if(page==='patches')loadPatches();
  $('#security-panel').hidden=page!=='security';if(page==='security')loadSecurity();
  $('#workspace-title').textContent={overview:'Dashboard',devices:'Computers',companies:'Customers & companies',groups:'Device groups',backups:'Backups',security:'Security',patches:'Patch Management',network:'Network Scan',directory:'Active Directory',scripts:'Script Marketplace',tickets:'Tickets',ai:'AI Agents',providers:'Provider Setup',monitoring:'Monitoring & Alerts'}[page];
  applyDashboard();
}
function render() {
  setFilter('#global-company',inventory.companies,'All companies');
  $('#company-count').textContent=inventory.companies.length;$('#location-count').textContent=inventory.locations.length;
  $('#device-count').textContent=inventory.devices.length;$('#online-count').textContent=inventory.devices.filter(d=>d.online).length;
  $('#connection').className='connection'+(inventory.error?' error':'');
  $('#connection').textContent=inventory.error?'Synchronization failed: '+inventory.error+(inventory.lastSync?' Showing last successful inventory from '+new Date(inventory.lastSync).toLocaleString()+'.':' No inventory verified yet.'):'Connected to MeshCentral · Last synchronized '+new Date(inventory.lastSync).toLocaleString()+' · Checks every 30 seconds';
  renderOrganisations();
  renderDeviceGroups();
  setFilter('#company-filter',inventory.companies,'All companies');
  setFilter('#location-filter',inventory.locations.filter(l=>!$('#company-filter').value||l.company_id===$('#company-filter').value),'All locations');
  setFilter('#group-filter',inventory.deviceGroups.filter(g=>(!$('#company-filter').value||g.company_id===$('#company-filter').value)&&(!$('#location-filter').value||g.location_id===$('#location-filter').value)),'All groups');
  $('#devices').innerHTML=devicesFiltered().map(d=>`<article class="device-card" data-device-card="${escape(d.id)}"><div class="device-card-heading"><span class="computer-icon" aria-hidden="true">▣</span><div><button class="text-button device-name" data-manage="${escape(d.id)}">${escape(d.name)}</button><p>${escape(d.company)}</p></div><span class="badge ${d.online?'':'offline'}">${d.online?'Online':'Offline'}</span></div><div class="device-metrics">${['CPU','Memory','Disk'].map(label=>`<div class="metric"><div><span>${label}</span><span class="metric-value" data-metric-value="${label.toLowerCase()}">Not available</span></div><div class="metric-track"><div data-metric-bar="${label.toLowerCase()}"></div></div></div>`).join('')}<p class="metric-status" data-metric-status>Awaiting readings</p></div><div class="device-info"><p>▦ ${escape(d.company)}</p><p>⌖ ${escape(d.location)}</p><p>${escape(d.os)}</p><p>Group: <strong>${escape(d.groupName)}</strong></p>${d.mapped?'':'<p class="warning">Group not linked to a company</p>'}</div><button class="primary connect-device" data-remote="${escape(d.id)}" ${!d.online||inventory.error?'disabled':''}>Connect Now ↗</button><div class="device-card-actions"><button data-edit-device="${escape(d.id)}">Edit</button><button class="danger" data-delete-device="${escape(d.id)}">Delete</button>${d.mapped?`<button data-invite="${escape(d.companyId)}">Agent</button>`:''}</div></article>`).join('')||'<p class="empty">No matching computers. Use Add device to generate an enrollment link.</p>';

  bind('[data-invite]',b=>enroll(b.dataset.invite));bind('[data-group-invite]',b=>{const g=inventory.deviceGroups.find(g=>g.id===b.dataset.groupInvite);enroll(g.company_id,g.location_id,g.id);});
  bind('[data-edit-device]',b=>editDevice(b.dataset.editDevice));bind('[data-delete-device]',b=>deleteDevice(b.dataset.deleteDevice));
  bind('[data-remote]',b=>openRemote(b.dataset.remote));bind('[data-manage]',b=>manageDevice(b.dataset.manage));
  bind('[data-edit-company]',b=>renameCompany(b.dataset.editCompany));bind('[data-company-location]',b=>locationForm(b.dataset.companyLocation));bind('[data-link-group]',b=>groupForm('', '', b.dataset.linkGroup));changePage(page);loadMetrics();renderDashboardOverview();
}
const metrics=new Map(),metricsPending=new Set();
function paintMetrics(d){
  const card=[...document.querySelectorAll('[data-device-card]')].find(c=>c.dataset.deviceCard===d.id);if(!card)return;
  const reading=metrics.get(d.id),status=card.querySelector('[data-metric-status]');
  if(!d.online){status.textContent='Computer offline';return;}
  if(!d.windows){status.textContent='Windows metrics only';return;}
  if(!reading){status.textContent='Collecting live readings…';return;}
  if(reading.error){status.textContent=reading.error;return;}
  for(const key of ['cpu','memory','disk']){
    card.querySelector(`[data-metric-value="${key}"]`).textContent=reading[key]+'%';
    card.querySelector(`[data-metric-bar="${key}"]`).style.width=reading[key]+'%';
  }
  status.textContent='System drive '+reading.diskName+' · Read at '+new Date(reading.checkedAt).toLocaleTimeString();
}
function renderDashboardOverview(){
 const total=inventory.devices.length,online=inventory.devices.filter(d=>d.online).length,offline=total-online;
 $('#endpoint-status').innerHTML=[['Online',online,'online'],['Offline',offline,'offline']].map(([name,count,kind])=>`<div class="endpoint-line"><span>${name}</span><div class="endpoint-track"><i data-endpoint-bar="${kind}"></i></div><strong>${count}</strong><small>${total?Math.round(count/total*100):0}%</small></div>`).join('');
 for(const [key,value]of [['online',online],['offline',offline]])$('#endpoint-status').querySelector(`[data-endpoint-bar="${key}"]`).style.width=(total?value/total*100:0)+'%';
 const fresh=inventory.devices.filter(d=>d.online).map(d=>metrics.get(d.id)).filter(m=>m&&!m.error&&Date.now()-Date.parse(m.checkedAt)<90000);
 $('#endpoint-readings').innerHTML='<div class="reading-summary">'+['cpu','memory','disk'].map(key=>`<div><span>${key==='cpu'?'CPU':key==='memory'?'Memory':'System disk'}</span><strong>${fresh.length?Math.round(fresh.reduce((sum,m)=>sum+m[key],0)/fresh.length)+'%':'—'}</strong></div>`).join('')+'</div><p class="muted">Average of '+fresh.length+' recently reporting computers.</p>';
 const links=acronisData.links||[],linked=inventory.devices.filter(d=>links.some(l=>l.node_id===d.id)).length;
 $('#protection-summary').innerHTML=`<div class="coverage-row"><div class="coverage-ring" id="connectivity-ring"><strong>${total?Math.round(online/total*100):0}%</strong></div><div><strong>Device connectivity</strong><p>${online} online · ${offline} offline</p></div></div><div class="coverage-row"><div class="coverage-ring violet" id="backup-link-ring"><strong>${acronisData.checkedAt&&total?Math.round(linked/total*100)+'%':'—'}</strong></div><div><strong>Acronis device links</strong><p>${acronisData.checkedAt?linked+' linked · '+(total-linked)+' not linked':'Open Backups to load provider data'}</p></div></div>`;
 $('#connectivity-ring').style.background=`conic-gradient(#08b489 ${total?online/total*360:0}deg,#e4f3ee 0deg)`;
 $('#backup-link-ring').style.background=`conic-gradient(#8b5cf6 ${total?linked/total*360:0}deg,#ece7fa 0deg)`;
 const alerts=[];
 if(inventory.error)alerts.push({title:'Inventory synchronization failed',detail:inventory.error});
 if(acronisData.error)alerts.push({title:'Acronis synchronization failed',detail:acronisData.error});
 for(const alert of (monitorData.alerts||[]).filter(a=>['active','acknowledged'].includes(a.status)))alerts.push({title:alert.rule_name,detail:alert.device_name+' · '+alert.company_name+' · '+alert.detail});
 $('#dashboard-alert-count').textContent=alerts.length;
 $('#priority-alerts').innerHTML=alerts.length?alerts.slice(0,5).map(a=>`<div class="priority-item"><span aria-hidden="true">!</span><div><strong>${escape(a.title)}</strong><p>${escape(a.detail)}</p></div></div>`).join(''):'<div class="quiet-alert"><span aria-hidden="true">✓</span><strong>No active monitoring alerts</strong><p>Enable monitoring rules to detect sustained conditions.</p></div>';
 $('#dashboard-device-table').innerHTML='<table><thead><tr><th>COMPUTER</th><th>COMPANY</th><th>STATUS</th><th>CPU</th><th>MEMORY</th><th>DISK</th><th>ACTION</th></tr></thead><tbody>'+devicesFiltered().map(d=>{const m=metrics.get(d.id),valid=d.online&&m&&!m.error&&Date.now()-Date.parse(m.checkedAt)<90000;return `<tr><td><button class="text-button" data-dashboard-device="${escape(d.id)}">${escape(d.name)}</button></td><td>${escape(d.company)}</td><td><span class="badge ${d.online?'':'offline'}">${d.online?'Online':'Offline'}</span></td><td>${valid?m.cpu+'%':'—'}</td><td>${valid?m.memory+'%':'—'}</td><td>${valid?m.disk+'%':'—'}</td><td><button data-dashboard-connect="${escape(d.id)}" ${!d.online||inventory.error?'disabled':''}>Connect ↗</button></td></tr>`;}).join('')+'</tbody></table>'+(total?'':'<p class="empty">Enroll a computer to see its inventory.</p>');
 bind('[data-dashboard-device]',b=>manageDevice(b.dataset.dashboardDevice));bind('[data-dashboard-connect]',b=>openRemote(b.dataset.dashboardConnect));
}
async function loadMetrics(){
  const queue=devicesFiltered();queue.forEach(paintMetrics);
  async function worker(){for(let d;(d=queue.shift());){
    if(!d.online||!d.windows||inventory.error||metricsPending.has(d.id))continue;
    const prior=metrics.get(d.id);if(prior&&Date.now()-prior.at<30000)continue;
    metricsPending.add(d.id);
    try{metrics.set(d.id,{...await api('telemetry',{nodeId:d.id}),at:Date.now()});}
    catch(error){metrics.set(d.id,{error:error.message,at:Date.now()});}
    finally{metricsPending.delete(d.id);const current=inventory.devices.find(x=>x.id===d.id);if(current)paintMetrics(current);renderDashboardOverview();}
  }}
  await Promise.all([worker(),worker()]);
}
function bind(selector,handler){document.querySelectorAll(selector).forEach(b=>b.onclick=()=>handler(b));}
async function refresh() {
  if(refreshing)return;refreshing=true;
  try{inventory=await api('inventory');$('#login').hidden=true;$('#workspace').hidden=false;$('#logout').hidden=false;render();}
  catch(error){if(!$('#workspace').hidden)message(error.message);}finally{refreshing=false;}
}
function showDialog(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());}
function actions(label){return `<p id="form-error" role="alert"></p><div class="actions"><button type="button" data-close>Cancel</button><button class="primary">${label}</button></div>`;}
function submitForm(id,route,onSuccess=refresh){$(id).onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;$('#form-error').textContent='';try{await api(route,Object.fromEntries(new FormData(e.target)));$('#modal').close();message('');await onSuccess();}catch(error){if($('#form-error'))$('#form-error').textContent=error.message;}finally{button.disabled=false;}};}
function setupRequired(){showDialog('<h2>Add device</h2><p class="muted">Set up your company once, or link an existing MeshCentral group. You can then add multiple locations, groups, and computers.</p><div class="actions"><button data-close>Cancel</button><button id="setup-company" class="primary">Set up company</button></div>');$('#setup-company').onclick=()=>{$('#modal').close();companyForm();};}
function enroll(companyId='',locationId='',groupId=''){
  if(!inventory.companies.length){setupRequired();return;}
  showDialog(`<h2>Add device</h2><p class="muted">Choose where this computer belongs. Existing computers and companies stay in place.</p><form id="add-device-form"><div class="steps"><span>1 Customer</span><span>2 Company</span><span>3 Install computer agent</span></div><label>Customer<select name="customerId"></select></label><label>Company<select name="companyId" required>${options(inventory.companies,companyId)}</select></label><details><summary>Advanced: location and device group</summary><label>Location<select name="locationId" required></select></label><label>Device group<select name="groupId" required></select></label></details><label>Operating system<input value="Windows — choose the matching installer on the enrollment page" readonly></label><p class="muted">The enrollment link is valid for 24 hours. The computer appears automatically once its agent is installed and connects.</p><p id="enrollment-error" role="alert"></p><div class="actions"><button type="button" data-close>Cancel</button><button type="button" id="enrollment-add-group">New group</button><button class="primary">Generate enrollment link</button></div></form>`);
  const form=$('#add-device-form'),company=form.elements.companyId,location=form.elements.locationId,group=form.elements.groupId;
  function updateGroups(){group.innerHTML=options(inventory.deviceGroups.filter(g=>g.company_id===company.value&&g.location_id===location.value),groupId||company.value);form.querySelector('.primary').disabled=!group.options.length;$('#enrollment-error').textContent=group.options.length?'':'This location has no device groups yet. Create a group first.';}
  function updateLocations(){location.innerHTML=options(inventory.locations.filter(l=>l.company_id===company.value),locationId||'location:'+company.value);updateGroups();}
  const customer=form.elements.customerId;
  customer.innerHTML=options(inventory.customers,inventory.companies.find(c=>c.id===company.value)?.customer_id,'All customers');
  customer.onchange=()=>{company.innerHTML=options(inventory.companies.filter(c=>!customer.value||c.customer_id===customer.value));locationId='';groupId='';updateLocations();};
  company.onchange=()=>{locationId='';groupId='';updateLocations();};location.onchange=()=>{groupId='';updateGroups();};updateLocations();
  $('#enrollment-add-group').onclick=()=>groupForm(company.value,location.value);
  form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('.primary');b.disabled=true;$('#enrollment-error').textContent='';try{await createInvitation(group.value);}catch(error){if($('#enrollment-error'))$('#enrollment-error').textContent=error.message;}finally{b.disabled=false;}};
}
async function createInvitation(groupId){
  const group=inventory.deviceGroups.find(g=>g.id===groupId);if(!group)throw new Error('Choose an assigned device group.');
  const value=await api('invitation',{groupId});
  showDialog(`<h2>Enroll a Windows computer</h2><p class="muted"><strong>${escape(group.company)} / ${escape(group.location)} / ${escape(group.name)}</strong></p><a class="invite" href="${escape(value.url)}" target="_blank" rel="noopener noreferrer">${escape(value.url)}</a><div class="callout">Enrollment link expires in 24 hours. Installed agents remain enrolled.</div><ol class="muted"><li>Open this link on the authorized Windows computer.</li><li>Download its matching Windows agent installer.</li><li>Run as administrator, choose Install, and explain that ongoing remote management will be enabled.</li><li>Keep it online. It appears in this company, location, and group on the next synchronization.</li></ol><p class="muted">You can use the same valid link for multiple computers in this group.</p><div class="actions"><button id="copy-invite">Copy link</button><button data-close>Close</button></div>`);
  $('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(value.url);$('#copy-invite').textContent='Copied';}catch{$('#copy-invite').textContent='Select and copy the link above';}};
}
function companyForm(){
  const assigned=new Set(inventory.deviceGroups.map(g=>g.id)),groups=inventory.groups.filter(g=>g.type===2&&!assigned.has(g.id));
  showDialog(`<h2>Add company</h2><form id="company-form"><label>Customer<select name="customerId">${options(inventory.customers,'','Unassigned customer')}</select></label><label>Company name<input name="name" required maxlength="120" placeholder="Company name"></label><label>Initial device group<select name="groupId"><option value="">Create a new agent device group</option>${groups.map(g=>`<option value="${escape(g.id)}">Link existing: ${escape(g.name)}</option>`).join('')}</select></label><p class="muted">We create a Main office location and assign the initial group there. Linking an existing group preserves its enrolled computers.</p>${organisationFields()}${actions('Save company')}</form>`);submitForm('#company-form','companies',async()=>{organisationTab='companies';$('#organisation-search').value='';await refresh();});
}
function locationForm(companyId=''){
  if(!inventory.companies.length){setupRequired();return;}
  showDialog(`<h2>Add location</h2><form id="location-form"><label>Company<select name="companyId" required>${options(inventory.companies,companyId)}</select></label><label>Location name<input name="name" maxlength="120" required placeholder="Head office, branch, or remote staff"></label>${actions('Save location')}</form>`);submitForm('#location-form','locations');
}
function groupForm(companyId='',locationId='',groupId=''){
  if(!inventory.companies.length){setupRequired();return;}
  const assigned=new Set(inventory.deviceGroups.map(g=>g.id)),available=inventory.groups.filter(g=>g.type===2&&!assigned.has(g.id));
  showDialog(`<h2>Add device group</h2><form id="group-form"><label>Company<select name="companyId" required>${options(inventory.companies,companyId)}</select></label><label>Location<select name="locationId" required></select></label><label>Group name<input name="name" required maxlength="120" placeholder="Workstations, servers, or laptops"></label><label>MeshCentral group<select name="groupId">${options(available,groupId,'Create a new agent device group')}</select></label><p class="muted">Each group belongs to one company location. Linking an existing group preserves its computers.</p>${actions('Save group')}</form>`);
  const form=$('#group-form');const update=()=>{form.elements.locationId.innerHTML=options(inventory.locations.filter(l=>l.company_id===form.elements.companyId.value),locationId);};form.elements.companyId.onchange=()=>{locationId='';update();};update();
  if(groupId)form.elements.name.value=available.find(g=>g.id===groupId)?.name||'';submitForm('#group-form','groups');
}
function renderDeviceGroups(){setFilter('#device-group-company',inventory.companies,'All companies');const query=$('#device-group-search').value.toLowerCase(),company=$('#device-group-company').value;
 $('#groups').innerHTML=inventory.deviceGroups.filter(g=>(!company||g.company_id===company)&&`${g.name} ${g.company} ${g.location}`.toLowerCase().includes(query)).map(g=>{const devices=inventory.devices.filter(d=>d.groupId===g.id),online=devices.filter(d=>d.online).length;return `<article class="organisation-card group-card"><div class="organisation-card-head"><span class="organisation-icon">▦</span><div><strong>${escape(g.name)}</strong><p>${escape(g.company)}</p></div><span class="organisation-plan">${g.id===g.company_id?'Default':'Group'}</span></div><div class="organisation-contact"><p>⌖ ${escape(g.location)}</p></div><div class="organisation-computers">▣ ${devices.length} Computer${devices.length===1?'':'s'} <span>${online} Online · ${devices.length-online} Offline</span></div><details><summary>Computers in this group</summary><div class="location-tags">${devices.map(d=>`<button class="text-button" data-manage="${escape(d.id)}">${escape(d.name)} · ${d.online?'Online':'Offline'}</button>`).join('')||'<p>No computers enrolled yet</p>'}</div></details><div class="organisation-actions"><button data-edit-device-group="${escape(g.id)}">♢ Edit</button><button class="danger" data-remove-device-group="${escape(g.id)}" ${g.id===g.company_id?'disabled title="Default groups are kept for company enrollment"':''}>♜ Delete</button></div><button class="primary group-enroll" data-group-invite="${escape(g.id)}">＋ Enroll device</button></article>`;}).join('')||'<p class="empty">No matching device groups.</p>';
 const assigned=new Set(inventory.deviceGroups.map(g=>g.id)),unassigned=inventory.groups.filter(g=>g.type===2&&!assigned.has(g.id)&&g.name.toLowerCase().includes(query));$('#unassigned-groups').innerHTML=unassigned.length?`<h3>Unassigned MeshCentral groups</h3><p class="muted">Link an existing group to its company and location.</p><div class="organisation-grid">${unassigned.map(g=>`<article class="organisation-card"><div class="organisation-card-head"><span class="organisation-icon">▦</span><div><strong>${escape(g.name)}</strong><p>Not linked to a company</p></div></div><button data-link-group="${escape(g.id)}">Link group</button></article>`).join('')}</div>`:'';
 bind('[data-group-invite]',b=>{const g=inventory.deviceGroups.find(g=>g.id===b.dataset.groupInvite);enroll(g.company_id,g.location_id,g.id);});bind('[data-manage]',b=>manageDevice(b.dataset.manage));bind('[data-link-group]',b=>groupForm('','',b.dataset.linkGroup));bind('[data-edit-device-group]',b=>editDeviceGroup(b.dataset.editDeviceGroup));bind('[data-remove-device-group]',b=>removeDeviceGroup(b.dataset.removeDeviceGroup));}
function editDeviceGroup(id){const g=inventory.deviceGroups.find(g=>g.id===id);showDialog(`<h2>Edit Device Group</h2><p class="muted">${escape(g.company)} / ${escape(g.location)}</p><form id="device-group-edit-form"><input type="hidden" name="id" value="${escape(id)}"><label>Group name<input name="name" required maxlength="120" value="${escape(g.name)}"></label><p class="muted">Updates the name shown in SkyBase. Company, location, computers and MeshCentral group stay linked.</p>${actions('Save group')}</form>`);submitForm('#device-group-edit-form','group-update');}
function removeDeviceGroup(id){const g=inventory.deviceGroups.find(g=>g.id===id);showDialog(`<h2>Delete group from SkyBase?</h2><p>${escape(g.name)} · ${escape(g.company)}</p><p class="muted">Only an empty, non-default group can be removed. Its MeshCentral group is kept and can be linked again.</p><p id="form-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button id="confirm-group-remove" class="danger">Delete group</button></div>`);$('#confirm-group-remove').onclick=async e=>{e.target.disabled=true;try{await api('group-delete',{id,confirm:true});$('#modal').close();await refresh();}catch(error){$('#form-error').textContent=error.message;}finally{e.target.disabled=false;}};}
$('#device-group-search').oninput=renderDeviceGroups;$('#device-group-company').onchange=renderDeviceGroups;

let organisationTab='customers';
function organisationFields(record={}){return `<div class="organisation-form-grid"><label>Contact name<input name="contact" maxlength="120" value="${escape(record.contact)}"></label><label>Email<input name="email" type="email" maxlength="254" value="${escape(record.email)}"></label><label>Phone<input name="phone" type="tel" maxlength="120" value="${escape(record.phone)}"></label><label>Service plan<select name="plan">${[['','Not specified'],['basic','Basic'],['professional','Professional'],['enterprise','Enterprise']].map(([id,label])=>`<option value="${id}" ${record.plan===id?'selected':''}>${label}</option>`).join('')}</select></label></div>`;}
function customerForm(id=''){const customer=inventory.customers.find(c=>c.id===id)||{};showDialog(`<h2>${id?'Edit':'Add'} Customer</h2><form id="customer-form">${id?`<input type="hidden" name="id" value="${escape(id)}">`:''}<label>Customer name<input name="name" required maxlength="120" value="${escape(customer.name)}" placeholder="Client organisation"></label>${organisationFields(customer)}${actions('Save customer')}</form>`);submitForm('#customer-form',id?'customer-update':'customers',async()=>{organisationTab='customers';await refresh();});}
function organisationCard(record,kind){const company=kind==='company',companies=company?[record]:inventory.companies.filter(c=>c.customer_id===record.id),devices=inventory.devices.filter(d=>companies.some(c=>c.id===d.companyId));return `<article class="organisation-card ${company?'company-row':''}"><div class="organisation-card-head"><span class="organisation-icon">▦</span><div><strong>${escape(record.name)}</strong><p>${escape(record.contact||'Contact not specified')}</p>${company?`<small>${escape(record.customer||'Unassigned customer')}</small>`:''}</div>${record.plan?`<span class="organisation-plan ${escape(record.plan)}">${escape(record.plan)}</span>`:''}</div><div class="organisation-contact"><p>✉ ${escape(record.email||'Email not specified')}</p><p>♧ ${escape(record.phone||'Phone not specified')}</p></div><div class="organisation-computers">▣ ${devices.length} Computer${devices.length===1?'':'s'}${!company?` · ${companies.length} Compan${companies.length===1?'y':'ies'}`:''}</div>${company?`<details><summary>Locations and computers</summary><div class="location-tags">${inventory.locations.filter(l=>l.company_id===record.id).map(l=>`<span>${escape(l.name)}</span>`).join('')}</div><div class="location-tags">${devices.map(d=>`<button class="text-button" data-manage="${escape(d.id)}">${escape(d.name)}</button>`).join('')||'<p>No computers enrolled yet</p>'}</div></details>`:''}<div class="organisation-actions"><button ${company?'data-edit-company':'data-edit-customer'}="${escape(record.id)}">♢ Edit</button><button class="danger" data-delete-organisation="${escape(record.id)}" data-kind="${kind}">♜ Delete</button></div>${company?`<div class="organisation-extra"><button data-invite="${escape(record.id)}">＋ Add device</button><button data-company-location="${escape(record.id)}">Add location</button></div>`:`<button class="organisation-company-link" data-customer-companies="${escape(record.id)}">View companies →</button>`}</article>`;}
function renderOrganisations(){const query=$('#organisation-search').value.toLowerCase(),matches=r=>[r.name,r.contact,r.email,r.phone,r.plan,r.customer].some(v=>String(v||'').toLowerCase().includes(query));$('#customer-cards').innerHTML=inventory.customers.filter(matches).map(c=>organisationCard(c,'customer')).join('')||'<p class="empty">No matching customers. Add a customer to organise its companies.</p>';$('#companies').innerHTML=inventory.companies.filter(matches).map(c=>organisationCard(c,'company')).join('')||'<p class="empty">No matching companies.</p>';$('#customer-cards').hidden=organisationTab!=='customers';$('#companies').hidden=organisationTab!=='companies';$('#customers-tab').classList.toggle('active',organisationTab==='customers');$('#companies-tab').classList.toggle('active',organisationTab==='companies');bind('[data-edit-customer]',b=>customerForm(b.dataset.editCustomer));bind('[data-delete-organisation]',b=>deleteOrganisation(b.dataset.deleteOrganisation,b.dataset.kind));bind('[data-customer-companies]',b=>{organisationTab='companies';$('#organisation-search').value=inventory.customers.find(c=>c.id===b.dataset.customerCompanies).name;renderOrganisations();});bind('[data-edit-company]',b=>renameCompany(b.dataset.editCompany));bind('[data-invite]',b=>enroll(b.dataset.invite));bind('[data-company-location]',b=>locationForm(b.dataset.companyLocation));bind('[data-manage]',b=>manageDevice(b.dataset.manage));}
function deleteOrganisation(id,kind){const row=inventory[kind==='company'?'companies':'customers'].find(r=>r.id===id);showDialog(`<h2>Delete ${kind}?</h2><p>${escape(row.name)}</p><p class="muted">Only empty records can be deleted. Linked companies, computer records, saved settings, and history prevent deletion. Existing MeshCentral groups are kept.</p><p id="form-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button id="confirm-organisation-delete" class="danger">Delete ${kind}</button></div>`);$('#confirm-organisation-delete').onclick=async e=>{e.target.disabled=true;try{await api(kind+'-delete',{id,confirm:true});$('#modal').close();await refresh();}catch(error){$('#form-error').textContent=error.message;}finally{e.target.disabled=false;}};}
$('#customers-tab').onclick=()=>{organisationTab='customers';renderOrganisations();};$('#companies-tab').onclick=()=>{organisationTab='companies';renderOrganisations();};$('#organisation-search').oninput=renderOrganisations;

function renameCompany(id){const company=inventory.companies.find(c=>c.id===id);showDialog(`<h2>Edit company</h2><form id="rename-company-form"><input type="hidden" name="id" value="${escape(id)}"><label>Customer<select name="customerId">${options(inventory.customers,company.customer_id,'Unassigned customer')}</select></label><label>Company name<input name="name" required maxlength="120" value="${escape(company.name)}"></label>${organisationFields(company)}${actions('Save company')}</form>`);submitForm('#rename-company-form','company-update');}
function openRemote(id){const d=inventory.devices.find(d=>d.id===id);if(d?.online&&!inventory.error)window.open(d.desktopUrl,'_blank','noopener,noreferrer');}
function editDevice(id){const d=inventory.devices.find(d=>d.id===id);showDialog(`<h2>Edit computer</h2><form id="edit-device-form"><input type="hidden" name="id" value="${escape(id)}"><label>Display name<input name="name" required maxlength="120" value="${escape(d.name)}"></label><p class="muted">Agent computer name: ${escape(d.agentName||d.name)}. This changes the name displayed in Maldoori.</p>${actions('Save computer')}</form>`);submitForm('#edit-device-form','device-update');}
function deleteDevice(id){const d=inventory.devices.find(d=>d.id===id);showDialog(`<h2>Delete computer</h2><p>Remove <strong>${escape(d.name)}</strong> from Maldoori?</p><p class="muted">It stays removed after synchronization. Its MeshCentral agent and Acronis backups remain installed and available in their consoles.</p><p id="form-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button class="danger" id="confirm-delete-device">Delete computer</button></div>`);$('#confirm-delete-device').onclick=async()=>{const b=$('#confirm-delete-device');b.disabled=true;try{await api('device-delete',{id,confirm:true});$('#modal').close();await refresh();}catch(error){$('#form-error').textContent=error.message;b.disabled=false;}};}
function manageDevice(id){const d=inventory.devices.find(d=>d.id===id);showDialog(`<h2>${escape(d.name)}</h2><p class="muted">${escape(d.company)} / ${escape(d.location)} / ${escape(d.groupName)}</p><div class="detail-grid"><div>Operating system<strong>${escape(d.os)}</strong></div><div>Connection<strong>${d.online?'Online':'Offline'}</strong></div></div><div class="actions"><button data-close>Close</button><button id="device-remote" class="primary" ${!d.online||inventory.error?'disabled':''}>Remote Desktop ↗</button></div>`);$('#device-remote').onclick=()=>openRemote(id);}
function renderAcronis(value){
  $('#acronis-status').textContent=value.error||(!value.configured?'Acronis credentials have not been configured on the server.':value.authenticated?'API authentication verified at '+new Date(value.checkedAt).toLocaleString()+'. Backup results are not yet verified.':'Credentials configured. Test the API connection.');
  $('#acronis-console').hidden=!value.authenticated;
  if(value.authenticated)$('#acronis-console').href=value.consoleUrl;
}
let acronisData={resources:[],tasks:[],links:[]},acronisLoading=false;
async function loadAcronis(){
  if(acronisLoading)return;acronisLoading=true;
  try{
    renderAcronis(await api('acronis'));acronisData=await api('acronis-inventory');
    if(acronisData.checkedAt&&!acronisData.error)renderAcronis({configured:true,authenticated:true,checkedAt:acronisData.checkedAt,consoleUrl:acronisData.consoleUrl});
    $('#acronis-inventory-status').textContent=acronisData.error||(acronisData.checkedAt?'Imported '+acronisData.resources.length+' resources · '+acronisData.tasks.length+' tasks · Checked '+new Date(acronisData.checkedAt).toLocaleString()+(acronisData.complete?'':'. Partial inventory; additional pages may be unavailable.'):'Waiting for Acronis credentials.');
    renderBackups();renderProviderChoice();renderDashboardOverview();
  }catch(error){$('#acronis-inventory-status').textContent=error.message;}finally{acronisLoading=false;}
}
let backupProviders={preferences:[],providers:[]},providersLoading=false;
async function loadBackupProviders(){if(providersLoading)return;providersLoading=true;try{backupProviders=await api('backup-providers');renderProviderChoice();renderBackups();}catch(error){$('#backup-provider-message').textContent=error.message;}finally{providersLoading=false;}}
function renderProviderChoice(){
 const providers=backupProviders.providers||[],selected=$('#backup-provider-view').value;$('#backup-provider-view').innerHTML=options(providers,providers.some(p=>p.id===selected)?selected:providers[0]?.id||'','Select provider');const id=$('#backup-provider-view').value,provider=providers.find(p=>p.id===id),apiProvider=provider?.adapter==='acronis-backup';$('#acronis-provider-panel').hidden=!apiProvider;$('#acronis-console').hidden=!apiProvider||!acronisData.consoleUrl;if(apiProvider){$('#acronis-console').textContent='Manage in '+provider.name+' ↗';if(provider.consoleUrl||acronisData.consoleUrl)$('#acronis-console').href=provider.consoleUrl||acronisData.consoleUrl;}
 const target=$('#custom-backup-providers');if(target.contains(document.activeElement))return;
 target.innerHTML=providers.filter(p=>p.adapter!=='acronis-backup').map(p=>{const companies=inventory.companies.filter(c=>backupProviders.preferences.some(v=>v.company_id===c.id&&v.provider===p.id));return `<section id="${p.id}-panel" ${p.id===id?'':'hidden'}><h3>${escape(p.name)}</h3><p class="muted">${escape(p.guidance||'Install the provider agent and configure backup plans in its management console. Status and backup controls are not connected to SkyBase.')}</p><button data-registry-edit="${p.id}" data-kind="backup">Edit provider settings</button><div id="${p.id}-companies">${companies.map(c=>`<h4>${escape(c.name)}</h4>`+(inventory.devices.filter(d=>d.companyId===c.id).map(d=>`<article class="backup-row"><span class="backup-drive-icon">▤</span><div class="backup-row-content"><div class="backup-row-title"><strong>${escape(d.name)}</strong><span class="backup-badge">Status not connected</span><span class="backup-type-badge">${escape(p.name)}</span></div><p>${escape(c.name)} · Schedule: View in provider</p></div><button data-provider-schedule="${p.id}" data-schedule-company="${escape(c.id)}">Manage schedule</button></article>`).join('')||'<p>No computers enrolled in this company.</p>')).join('')||'<p class="empty">No companies selected this provider.</p>'}</div><form id="${p.id}-settings-form" data-console-provider="${p.id}"><label>Management console URL<input name="consoleUrl" type="url" maxlength="1000" value="${escape(p.consoleUrl)}"></label><p id="${p.id}-settings-error" role="status"></p><div class="actions"><button type="submit">Save console link</button><a id="${p.id}-console" class="button-link primary" href="${escape(p.consoleUrl)}" target="_blank" rel="noopener noreferrer" ${p.consoleUrl?'':'hidden'}>Open provider console ↗</a></div></form></section>`;}).join('');
 bind('[data-provider-schedule]',b=>scheduleBackup(b.dataset.scheduleCompany));bind('[data-registry-edit]',b=>openRegistryEditor(b.dataset.kind,b.dataset.registryEdit));document.querySelectorAll('[data-console-provider]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await api('provider-console',{kind:'backup',provider:form.dataset.consoleProvider,consoleUrl:form.elements.consoleUrl.value});await loadBackupProviders();}catch(error){$('#'+form.dataset.consoleProvider+'-settings-error').textContent=error.message;}});
}

function scheduleBackup(companyId=''){
 showDialog(`<h2>Schedule backup</h2><p class="muted">Select a company to open its backup provider. Schedules are configured and saved in the provider console.</p><label>Company<select id="schedule-company">${options(inventory.companies,companyId,'Select company')}</select></label><div id="schedule-provider-guide"></div><div class="actions"><button data-close>Close</button></div>`);
 const update=()=>{const company=$('#schedule-company').value;if(!company){$('#schedule-provider-guide').textContent='Choose a company to continue.';return;}const id=backupProviders.preferences.find(p=>p.company_id===company)?.provider,provider=backupProviders.providers.find(p=>p.id===id);if(!provider){$('#schedule-provider-guide').textContent='Choose a backup provider for this company first.';return;}const label=escape(provider.name),url=provider.consoleUrl||(provider.adapter==='acronis-backup'?acronisData.consoleUrl:'');
 $('#schedule-provider-guide').innerHTML=`<p><strong>${label}</strong></p><p>Select the computer in ${label}, then configure its backup plan, storage destination, schedule, and retention.</p>${url?`<a class="button-link primary" href="${escape(url)}" target="_blank" rel="noopener noreferrer">Open ${label} ↗</a>`:'<p class="muted">Configure this provider’s console connection on the Backups page first.</p>'}`;
 };$('#schedule-company').onchange=update;update();
}
$('#schedule-backup').onclick=()=>scheduleBackup($('#backup-company').value);
$('#backup-provider-view').onchange=renderProviderChoice;
$('#choose-backup-provider').onclick=()=>{showDialog(`<h2>Choose company backup provider</h2><form id="provider-choice-form"><label>Company<select name="companyId" required>${options(inventory.companies,'','Select company')}</select></label><label>Backup provider<select name="provider">${options(backupProviders.providers,'','Not selected')}</select></label><p class="muted">This saves the company’s choice. It does not install agents, move existing backups, or cancel either subscription.</p>${actions('Save provider')}</form>`);const form=$('#provider-choice-form');form.elements.companyId.onchange=()=>{form.elements.provider.value=backupProviders.preferences.find(p=>p.company_id===form.elements.companyId.value)?.provider||'';};form.onsubmit=async e=>{e.preventDefault();try{await api('backup-provider',Object.fromEntries(new FormData(form)));$('#modal').close();await loadBackupProviders();$('#backup-provider-message').textContent='Company backup provider saved.';}catch(error){$('#form-error').textContent=error.message;}};};


function backupDate(value){return value&&Number.isFinite(Date.parse(value))?new Date(value).toLocaleString():'Not verified';}
function renderBackups(){
  const linked=inventory.devices.filter(d=>acronisData.links.some(l=>l.node_id===d.id)).length;
  $('#backup-summary').innerHTML=`<div><span>Computers</span><strong>${inventory.devices.length}</strong></div><div><span>Linked to Acronis</span><strong>${linked}</strong></div><div><span>Need linking</span><strong>${inventory.devices.length-linked}</strong></div>`;
  setFilter('#backup-company',inventory.companies,'All companies');
  const query=$('#backup-search').value.toLowerCase(),company=$('#backup-company').value;
  const devices=inventory.devices.filter(d=>(!company||d.companyId===company)&&`${d.name} ${d.company}`.toLowerCase().includes(query));
  $('#acronis-computers').innerHTML=devices.map(d=>{
    const link=acronisData.links.find(l=>l.node_id===d.id),resource=acronisData.resources.find(r=>r.id===link?.resource_id),backup=acronisData.backupResults?.find(b=>b.resourceId===resource?.id),task=backup?.latestTask;
    let label=!link?'Not linked':!resource?'Resource unavailable':!task?'No verified task':task.state==='completed'&&task.result==='ok'?'Last task succeeded':task.state==='completed'?'Last task needs attention':'Task: '+task.state;
    if(acronisData.error)label='Status unavailable';
    const success=!acronisData.error&&task?.state==='completed'&&task?.result==='ok';
    return `<article class="backup-row"><span class="backup-drive-icon" aria-hidden="true">▤</span><div class="backup-row-content"><div class="backup-row-title"><strong>${escape(d.name)}</strong><span class="backup-badge ${success?'success':''}">${escape(label)}</span><span class="backup-type-badge">${escape(backupProviders.providers.find(p=>p.adapter==='acronis-backup')?.name||'Backup API')}</span></div><p>${escape(d.company)} · Schedule: <strong>View in provider</strong></p><p class="muted">Last successful task: ${escape(backupDate(backup?.lastSuccessfulTaskAt))}</p></div><div class="backup-row-actions">${resource&&acronisData.consoleUrl?`<button data-backup-info="${escape(d.id)}">↶ Restore…</button>`:''}<button data-backup-info="${escape(d.id)}" title="View backup details">◷ Details</button><button data-acronis-link="${escape(d.id)}" ${acronisData.error||!acronisData.checkedAt?'disabled':''}>✎ ${link?'Edit link':'Link device'}</button>${link?`<button class="danger" data-backup-unlink="${escape(d.id)}">Remove link</button>`:''}</div></article>`;

  }).join('')||'<p class="empty">No matching computers.</p>';
  const allowed=['D332948D-A7A9-4E07-B76C-253DCF6E17FB','1B6CB334-6CB5-4760-AE3C-B96A973D5A99'];
  const tasks=acronisData.tasks.filter(t=>$('#backup-history-filter').value==='all'||allowed.includes(t.type.toUpperCase())).sort((a,b)=>(Date.parse(b.completedAt||b.startedAt)||0)-(Date.parse(a.completedAt||a.startedAt)||0));
  $('#acronis-tasks').innerHTML='<table><thead><tr><th>CUSTOMER</th><th>ACTIVITY</th><th>RESULT</th><th>COMPLETED</th></tr></thead><tbody>'+tasks.map(t=>`<tr><td>${escape(t.tenant)}</td><td>${escape(t.title)}</td><td>${escape(t.state==='completed'&&t.result==='ok'?'Succeeded':t.state+' / '+t.result)}</td><td>${escape(backupDate(t.completedAt))}</td></tr>`).join('')+'</tbody></table>'+(tasks.length?'':'<p class="empty">No matching activities returned.</p>');
  bind('[data-acronis-link]',b=>linkAcronis(b.dataset.acronisLink));
  bind('[data-backup-unlink]',b=>{const d=inventory.devices.find(d=>d.id===b.dataset.backupUnlink);showDialog(`<h2>Remove backup link</h2><p>Remove the SkyBase Acronis link for ${escape(d.name)}?</p><p class="muted">This leaves the provider’s backups, agent, and schedule in place.</p><p id="unlink-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button class="danger" id="confirm-backup-unlink">Remove link</button></div>`);$('#confirm-backup-unlink').onclick=async()=>{const button=$('#confirm-backup-unlink');button.disabled=true;try{await api('acronis-link',{nodeId:d.id,resourceId:''});$('#modal').close();await loadAcronis();}catch(error){$('#unlink-error').textContent=error.message;button.disabled=false;}};});

  bind('[data-backup-info]',b=>{const d=inventory.devices.find(d=>d.id===b.dataset.backupInfo),link=acronisData.links.find(l=>l.node_id===d.id),backup=acronisData.backupResults?.find(r=>r.resourceId===link?.resource_id);showDialog(`<h2>${escape(d.name)} backup</h2><p class="muted">${escape(d.company)}</p><p>Last successful backup task: ${escape(backupDate(backup?.lastSuccessfulTaskAt))}</p><p class="muted">${backup?.latestTask?'Only tasks with a unique Acronis resource reference are shown.':'No uniquely matched backup task has been returned for this computer.'}</p><p class="muted">To run a backup, edit its schedule, or restore files, open the Acronis console and select this computer.</p><div class="actions"><button data-close>Close</button>${acronisData.consoleUrl?`<a class="button-link primary" href="${escape(acronisData.consoleUrl)}" target="_blank" rel="noopener noreferrer">Manage in Acronis ↗</a>`:''}</div>`);});
}
const networkTypes={unknown:'Unknown',workstation:'Workstations',server:'Servers',printer:'Printers',phone:'Phones',network:'Network devices'};
const monitorLabels={offline:'Computer offline',cpu:'CPU usage',memory:'Memory usage',disk:'System disk usage',service:'Windows service stopped',backup:'Unsuccessful Acronis backup task'};let monitorData={rules:[],alerts:[],counts:[],health:{},recentObservations:[]},monitorTab='alerts',monitorLoading=false,monitorTimer;
async function loadMonitoring(){if(monitorLoading)return;clearTimeout(monitorTimer);monitorLoading=true;try{monitorData=await api('monitoring');renderMonitoring();renderDashboardOverview();if(monitorData.health.running&&page==='monitoring')monitorTimer=setTimeout(loadMonitoring,2000);}catch(error){$('#monitor-message').textContent=error.message;}finally{monitorLoading=false;}}
function renderMonitoring(){const counts=Object.fromEntries(monitorData.counts.map(c=>[c.status,c.count])),enabled=monitorData.rules.filter(r=>r.enabled).length;$('#monitor-health').textContent=monitorData.health.running?'Monitoring check is running…':monitorData.health.error||`${enabled} enabled rules · Last check: ${monitorData.health.checkedAt?ticketDate(monitorData.health.checkedAt)+' CT':'Not checked'} · ${monitorData.health.evaluated||0} known observations · ${monitorData.health.unavailable||0} unavailable readings`;
 $('#monitor-summary').innerHTML=[[counts.active||0,'Active'],[counts.acknowledged||0,'Acknowledged'],[counts.recovered||0,'Recovered'],[enabled,'Enabled Rules']].map(([n,label])=>`<article><strong>${n}</strong><span>${label}</span></article>`).join('');$('#monitor-alert-list').hidden=monitorTab!=='alerts';$('#monitor-rule-list').hidden=monitorTab!=='rules';$('#monitor-coverage').hidden=monitorTab!=='coverage';document.querySelectorAll('[data-monitor-tab]').forEach(b=>b.classList.toggle('primary',b.dataset.monitorTab===monitorTab));const status=$('#monitor-status-filter').value,alerts=monitorData.alerts.filter(a=>status==='all'||(status==='active'?['active','acknowledged'].includes(a.status):a.status===status));
 $('#monitor-alert-list').innerHTML=alerts.map(a=>`<article class="ticket-card"><div class="ticket-content"><div class="ticket-title"><strong>${escape(a.rule_name)}</strong><span class="ticket-badge priority-${a.severity==='critical'?'urgent':'medium'}">${a.severity}</span><span class="ticket-badge">${a.status}</span></div><p>${escape(a.device_name)} · ${escape(a.company_name)}</p><p class="ticket-description">${escape(a.detail)}</p><p class="ticket-meta">Started ${ticketDate(a.created_at)} CT · Last update ${ticketDate(a.updated_at)} CT</p>${['active','acknowledged'].includes(a.status)&&(a.observation_state==='unknown'||!a.observation_at||Date.now()-Date.parse(a.observation_at)>120000)?'<p class="muted">Current evidence unavailable or stale; recovery has not been confirmed.</p>':''}${a.closure_reason?`<p class="muted">${escape(a.closure_reason)}</p>`:''}</div><div class="ticket-actions">${a.status==='active'?`<button data-monitor-ack="${a.id}">Acknowledge</button>`:''}${a.ticket_id&&!a.ticket_deleted?`<button data-monitor-ticket="${a.ticket_id}">Open SB-${String(a.ticket_number).padStart(4,'0')}</button>`:a.ticket_deleted?'<small>Linked ticket removed</small>':'<small>No automatic ticket</small>'}</div></article>`).join('')||'<section class="panel empty">No matching alerts. Enabled rules need fresh evidence for their configured duration.</section>';
 $('#monitor-rule-list').innerHTML=monitorData.rules.map(r=>`<article class="organisation-card"><div class="organisation-card-head"><span class="organisation-icon">⌁</span><div><strong>${escape(r.name)}</strong><p>${monitorLabels[r.type]}</p></div><span class="organisation-plan">${r.enabled?'Enabled':'Disabled'}</span></div><p class="muted">${escape(r.company||'All companies')} · Duration: ${r.duration} min</p><p class="muted">${['cpu','memory','disk'].includes(r.type)?`Trigger ≥${r.threshold}% · Recover ≤${r.recovery}%`:r.type==='service'?'Service: '+escape(r.service_name):monitorLabels[r.type]}</p><p class="muted">${r.severity} · ${r.auto_ticket?'Automatic ticket enabled':'Alert only'}</p><div class="organisation-actions"><button data-monitor-rule-edit="${r.id}">Edit</button><button class="danger" data-monitor-rule-delete="${r.id}">Delete</button></div></article>`).join('')||'<p>No monitoring rules.</p>';
 $('#monitor-coverage').innerHTML='<table class="directory-table"><thead><tr><th>Computer</th><th>Rule</th><th>State</th><th>Evidence / reason</th></tr></thead><tbody>'+monitorData.recentObservations.map(s=>`<tr><td>${escape(inventory.devices.find(d=>d.id===s.node_id)?.name||s.node_id)}</td><td>${escape(s.rule_name)}</td><td>${s.state}</td><td>${escape(s.detail)}${s.since?' · Threshold first seen '+ticketDate(s.since)+' CT':''}</td></tr>`).join('')+'</tbody></table>';
 bind('[data-monitor-ack]',async b=>{try{await api('monitor-acknowledge',{id:b.dataset.monitorAck});await loadMonitoring();}catch(error){$('#monitor-message').textContent=error.message;}});bind('[data-monitor-ticket]',async b=>{changePage('tickets',true);ticketIntegration=await api('ticket-integrations');await viewTicket(b.dataset.monitorTicket);});bind('[data-monitor-rule-edit]',b=>monitorRuleForm(b.dataset.monitorRuleEdit));bind('[data-monitor-rule-delete]',b=>deleteMonitorRule(b.dataset.monitorRuleDelete));}
function monitorRuleForm(id=''){const r=monitorData.rules.find(r=>r.id===id)||{type:'disk',threshold:85,recovery:80,duration:5,severity:'warning'};showDialog(`<div class="patch-modal-heading"><h2>${id?'Edit':'Add'} Monitoring Rule</h2><button data-close aria-label="Close">×</button></div><form id="monitor-rule-form">${id?`<input name="id" type="hidden" value="${id}">`:''}<div class="ticket-form-grid"><label>Rule name<input name="name" required maxlength="120" value="${escape(r.name)}"></label><label>Condition<select id="monitor-rule-type" name="type">${Object.entries(monitorLabels).map(([v,label])=>`<option value="${v}" ${r.type===v?'selected':''}>${label}</option>`).join('')}</select></label><label>Company<select name="companyId">${options(inventory.companies,r.company_id||'','All companies')}</select></label><label>Sustained duration (minutes)<input name="duration" type="number" required min="1" max="1440" value="${r.duration}"></label></div><div id="monitor-percentage-fields" class="ticket-form-grid"><label>Trigger at / above (%)<input name="threshold" type="number" min="1" max="100" value="${r.threshold}"></label><label>Recover at / below (%)<input name="recovery" type="number" min="0" max="99" value="${r.recovery}"></label></div><label id="monitor-service-field">Windows service name<input name="serviceName" maxlength="128" value="${escape(r.service_name)}" placeholder="Spooler"></label><label>Severity<select name="severity"><option value="warning" ${r.severity==='warning'?'selected':''}>Warning</option><option value="critical" ${r.severity==='critical'?'selected':''}>Critical</option></select></label><label class="ticket-setting-check"><input name="enabled" type="checkbox" ${r.enabled?'checked':''}> Enable this rule</label><label class="ticket-setting-check"><input name="autoTicket" type="checkbox" ${r.auto_ticket?'checked':''}> Create a ticket automatically when an alert opens</label><p class="muted">Rule edits reset pending evidence and close previous alerts without resolving their tickets. Recovery requires fresh evidence. CPU, memory, disk and service readings require an online Windows agent. Service monitoring is read-only; backup failures require a uniquely linked Acronis task. Unknown or stale readings never create failure tickets.</p>${actions('Save Rule')}</form>`);const update=()=>{const type=$('#monitor-rule-type').value;$('#monitor-percentage-fields').hidden=!['cpu','memory','disk'].includes(type);$('#monitor-service-field').hidden=type!=='service';$('#monitor-rule-form').elements.serviceName.required=type==='service';};update();$('#monitor-rule-type').onchange=update;$('#monitor-rule-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;const values=Object.fromEntries(new FormData(e.target));values.enabled=e.target.elements.enabled.checked;values.autoTicket=e.target.elements.autoTicket.checked;try{await api('monitor-rule-save',values);$('#modal').close();await loadMonitoring();}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}};}
