$('#monitor-add').onclick=()=>monitorRuleForm();$('#monitor-check').onclick=async()=>{try{await api('monitor-check',{});await loadMonitoring();}catch(error){$('#monitor-message').textContent=error.message;}};$('#monitor-status-filter').onchange=renderMonitoring;bind('[data-monitor-tab]',b=>{monitorTab=b.dataset.monitorTab;renderMonitoring();});

