function providerForm(kind,id=''){const p=registryData[kind].find(v=>v.id===id)||{name:'',adapter:'console'},adapters=registryData.adapters.filter(a=>a.kinds.includes(kind));showDialog(`<div class="patch-modal-heading"><h2>${id?'Edit':'Add'} ${kind==='backup'?'Backup':'Antivirus'} Provider</h2><button data-close aria-label="Close">×</button></div><form id="provider-registry-form"><input name="kind" type="hidden" value="${kind}">${id?`<input name="id" type="hidden" value="${escape(id)}">`:''}<div class="ticket-form-grid"><label>Provider name<input name="name" maxlength="120" required value="${escape(p.name)}" placeholder="Your backup or antivirus provider"></label><label>Integration adapter<select name="adapter" id="registry-adapter">${adapters.map(a=>`<option value="${a.id}" ${p.adapter===a.id?'selected':''}>${escape(a.name)}</option>`).join('')}</select></label></div><label>Management console URL<input name="consoleUrl" type="url" maxlength="1000" value="${escape(p.consoleUrl)}" placeholder="https://your-provider-console.example"></label><label>Setup instructions / notes<textarea name="guidance" maxlength="2000" rows="3">${escape(p.guidance)}</textarea></label><div id="provider-api-fields" ${p.adapter==='console'?'hidden':''}><label>Acronis data center origin<input name="endpoint" type="url" maxlength="300" value="${escape(p.endpoint)}" placeholder="https://us15-cloud.acronis.com"></label><div class="ticket-form-grid"><label>API client ID<input name="clientId" maxlength="300" value="${escape(p.clientId)}"></label><label>API client secret<input name="secret" type="password" autocomplete="new-password" maxlength="1000" placeholder="${p.secretSaved?'Saved — leave blank to keep':'Enter client secret'}"></label></div></div><p class="muted">Console-only providers can be assigned to companies but do not connect device status or remote actions. The Acronis adapter connects backup inventory; one Acronis API account is supported. Secrets stay on the server and are not returned to this form.</p>${actions('Save Provider')}</form>`);const update=()=>{const enabled=$('#registry-adapter').value!=='console';$('#provider-api-fields').hidden=!enabled;for(const name of ['endpoint','clientId'])$('#provider-registry-form').elements[name].required=enabled;$('#provider-registry-form').elements.secret.required=enabled&&!p.secretSaved;};$('#registry-adapter').onchange=update;update();submitForm('#provider-registry-form','provider-save',async()=>{await loadProviderRegistry();await loadBackupProviders();await loadSecurity();});}
function deleteProvider(kind,id){const provider=registryData[kind].find(p=>p.id===id);showDialog(`<h2>Delete provider?</h2><p>${escape(provider.name)}</p><p class="muted">Reassign or clear company choices first. Stored provider settings are removed; vendor subscriptions, agents and backups remain in place.</p><p id="form-error" role="alert"></p><div class="actions"><button data-close>Cancel</button><button id="provider-delete-confirm" class="danger">Delete Provider</button></div>`);$('#provider-delete-confirm').onclick=async e=>{e.target.disabled=true;try{await api('provider-delete',{kind,id,confirm:true});$('#modal').close();await loadProviderRegistry();await loadBackupProviders();await loadSecurity();}catch(error){$('#form-error').textContent=error.message;}finally{e.target.disabled=false;}};}
