$('#backup-provider-setup').onclick=()=>showProviderSetup('backup');$('#security-provider-setup').onclick=()=>showProviderSetup('security');$('#provider-add').onclick=()=>providerForm(registryKind);bind('[data-provider-kind]',b=>{registryKind=b.dataset.providerKind;renderProviderRegistry();});

