function renderAgents(){$('#ai-agent-list').innerHTML=agentData.agents.map(a=>`<article class="organisation-card ai-agent-card"><div class="organisation-card-head"><span class="organisation-icon">✦</span><div><strong>${escape(a.name)}</strong><p>${agentProviders[a.provider]}</p></div>${agentData.defaultId===a.id?'<span class="organisation-plan">Default</span>':''}</div><p class="ai-model">Model / deployment: <strong>${escape(a.model)}</strong></p><p class="muted">${a.auto?'Automatic email reviews':'Manual reviews'} · Key saved</p><p class="ai-test ${a.testStatus}">${a.testStatus==='passed'?'✓ Connection test passed':a.testStatus==='failed'?'Connection test failed':'Connection not tested'}${a.testedAt?' · '+ticketDate(a.testedAt)+' CT':''}</p>${a.testDetail?`<p class="muted">${escape(a.testDetail)}</p>`:''}<div class="organisation-actions"><button data-agent-edit="${a.id}">Edit</button><button class="danger" data-agent-delete="${a.id}">Delete</button></div><div class="organisation-extra"><button data-agent-test="${a.id}">Test Connection</button><button data-agent-default="${agentData.defaultId===a.id?'':a.id}">${agentData.defaultId===a.id?'Disable Default':'Use as Default'}</button></div></article>`).join('')||'<section class="panel empty">No AI agents configured. Add an agent with your provider API key.</section>';bind('[data-agent-edit]',b=>agentForm(b.dataset.agentEdit));bind('[data-agent-delete]',b=>removeAgent(b.dataset.agentDelete));bind('[data-agent-default]',b=>agentAction('ai-agent-default',{id:b.dataset.agentDefault},b));bind('[data-agent-test]',b=>agentAction('ai-agent-test',{id:b.dataset.agentTest},b));}
