function agentForm(id=''){const a=agentData.agents.find(a=>a.id===id)||{provider:'openai',model:'gpt-4.1-mini'};showDialog(`<div class="patch-modal-heading"><h2>${id?'Edit':'Add'} AI Agent</h2><button data-close aria-label="Close">×</button></div><form id="ai-agent-form">${id?`<input name="id" type="hidden" value="${escape(id)}">`:''}<div class="ticket-form-grid"><label>Agent name<input name="name" required maxlength="100" value="${escape(a.name)}" placeholder="Help desk analyst"></label><label>Provider<select name="provider" id="agent-provider">${Object.entries(agentProviders).map(([value,label])=>`<option value="${value}" ${a.provider===value?'selected':''}>${label}</option>`).join('')}</select></label><label>Model / Azure deployment<input id="agent-model" name="model" required maxlength="120" value="${escape(a.model)}" placeholder="Model ID from your provider console"></label><label>API key<input name="apiKey" type="password" autocomplete="new-password" maxlength="1000" placeholder="${id?'Saved — leave blank to keep':'Enter provider API key'}" ${id?'':'required'}></label></div><label id="agent-endpoint-label" ${a.provider==='azure'?'':'hidden'}>Azure resource endpoint<input name="endpoint" type="url" maxlength="300" value="${escape(a.endpoint)}" placeholder="https://your-resource.openai.azure.com"></label><label>Agent instructions<textarea name="instructions" rows="4" maxlength="3000" placeholder="Prefer simple steps. Ask for symptoms before suggesting changes.">${escape(a.instructions)}</textarea></label><label class="ticket-setting-check"><input name="auto" type="checkbox" ${a.auto?'checked':''}> Automatically review incoming email tickets when this agent is default</label><label class="ticket-setting-check"><input name="makeDefault" type="checkbox" ${agentData.defaultId===id?'checked':''}> Use as default for ticket reviews</label><p class="muted">Ticket text and recent notes go to the chosen provider. API billing applies. Instructions guide suggestions; they do not authorize automated fixes. Changing provider requires a new API key.</p>${actions('Save Agent')}</form>`);$('#agent-provider').onchange=e=>{const provider=e.target.value;$('#agent-endpoint-label').hidden=provider!=='azure';$('#ai-agent-form [name="endpoint"]').required=provider==='azure';if(provider!==a.provider){$('#agent-model').value=provider==='openai'?'gpt-4.1-mini':'';$('#ai-agent-form [name="apiKey"]').required=true;}else $('#ai-agent-form [name="apiKey"]').required=!id;};$('#ai-agent-form [name="endpoint"]').required=a.provider==='azure';$('#ai-agent-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;const values=Object.fromEntries(new FormData(e.target));values.auto=e.target.elements.auto.checked;values.makeDefault=e.target.elements.makeDefault.checked;try{await api('ai-agent-save',values);$('#modal').close();await loadAgents();}catch(error){$('#form-error').textContent=error.message;}finally{button.disabled=false;}};}
